    Counters.Counter private _tokenIDs;
    Counters.Counter private _dropIDs;
    Counters.Counter private _animalIDs;

    // Address for the market
    address public marketContract;

    address[] drops;

    constructor() ERC721("CryptoZoo", "ANML") { }

