    using Counters for Counters.Counter;
    Counters.Counter private _setIDs;

    Data data;

    Animal[] animals;
    string name;
    string description;
    uint256 yield;
    uint256 boost;
    uint256 probability;

    constructor(
        string memory _name,
        string memory _description,
        Data memory _data,
